      "path": "index.js",
      "content": "/**
 * harness-github —— DeepSeek Harness GitHub 插件(连接器优先)。
 *
 * 功能对齐 Codex GitHub 插件:检查 PR、分诊 issue、调试失败的 Actions 检查、
 * 处理 review 反馈、准备代码更改以供审查 + 发布信息查看。
 *
 * 设计要点:
 *  - 认证零额外操作:gh CLI 登录态 → GITHUB_TOKEN(env / ctx.credentials)→ 公开仓库匿名只读;
 *  - 传输层 gh CLI 优先,REST(fetch)回退,429/5xx 指数退避(见 lib/github.js);
 *  - 只读工具免审批;所有写操作经 ctx.approval 人工审批(缺失即拒绝,绝不静默放行);
 *  - 系统提示注入 github:workflow section(四段工作流 + 权限说明 + 何时直接跑 gh)。
 *
 * 加载方式:作为 dsh bundle(声明 dsh.bundle.patch)被 `dsh plugin add harness-github`
 * 装进任意 profile(web / tui / headless 通用)。
 */
import z from '@deepseek-ai/schemastery'
import { defineTool } from '@deepseek-ai/dsh-tools'
import { createGitHubClient } from './lib/github.js'
import { createReadTools } from './lib/tools-read.js'
import { createWriteTools } from './lib/tools-write.js'
import { buildWorkflowSection } from './lib/workflow.js'

/** 稳定插件名。 */
export const name = 'harness-github'

/**
 * 需要的服务:schema 用 tools / systemPrompt 均必须存在;
 * approval / credentials 为可选服务(访问时用 ctx.get 防御,缺失 fail-closed)。
 */
export const inject = ['systemPrompt', 'tools']

/** 插件配置。 */
export const Config = z.object({
  /** system-prompt section 的排序位置(越小越靠前)。 */
  sectionOrder: z.number().default(160),
  /** GitHub REST API 基础地址(二期支持 Enterprise host,现在保留默认)。 */
  apiBaseUrl: z.string().default('https://api.github.com'),
})

/**
 * 应用插件:创建传输层客户端、注册系统提示 section、注册全部工具。
 * @param ctx - Cordis 上下文。
 * @param config - 插件配置。
 */
export function apply(ctx, config) {
  const client = createGitHubClient({
    config,
    logger: ctx.logger,
    // 每一步操作重新解析凭据(服务缺失返回 undefined → 匿名/失败路径)。
    resolveCredential: (ref) => {
      const credentials = ctx.get('credentials')
      return credentials ? credentials.resolve(ref) : Promise.resolve(undefined)
    },
  })

  // 系统提示 section:注入 GitHub 工作流指引(函数形式,每次组装求值)。
  // 防御:即使宿主未应用 Config 默认值(sectionOrder 缺失)也不至于注册失败。
  ctx.systemPrompt.section({
    name: 'github:workflow',
    order: config.sectionOrder ?? 160,
    text: () => buildWorkflowSection(),
  })

  // 工具注册:只读(免审批)+ 写(全部经 ctx.approval)。
  for (const tool of [...createReadTools(client), ...createWriteTools({ client, ctx })]) {
    ctx.tools.register(defineTool(tool))
  }
}

export default { name, inject, Config, apply }"
