    {
      "path": "lib/github.js",
      "content": "/**
 * harness-github —— 传输层(gh CLI 优先 + REST 回退)。
 *
 * 认证解析(单次操作,按顺序):
 *   1. gh CLI 已登录(`gh auth status` 有效)→ 直接复用 gh,免 token;
 *   2. GITHUB_TOKEN(进程环境变量 / ctx.credentials 凭据库)→ REST(fetch)带 Bearer;
 *   3. 公开仓库只读:无任何凭据时走 REST 匿名调用(速率受限);
 *   4. 全都没有且要写操作 → GitHubAuthError,唯一指引 AUTH_GUIDANCE。
 *
 * 传输:gh 可用且已登录 → `gh api`(与 REST 同路径同 JSON,便于互操作与回退);
 * gh 不存在或未登录 → REST fetch;429/5xx 指数退避(带 jitter,尊重 Retry-After)。
 * token 永不进日志、永不写入任何配置文件。
 */
import { spawn } from 'node:child_process'

/** 凭据缺失/写权限不足时的唯一指引文案。 */
export const AUTH_GUIDANCE =
  '运行 `gh auth login` 或设置 `GITHUB_TOKEN` 环境变量后重试。(Run `gh auth login` or set the `GITHUB_TOKEN` environment variable, then retry.)'

/** 默认 REST API 基础地址。 */
export const DEFAULT_API_BASE = 'https://api.github.com'

/** 可重试的 HTTP 状态。 */
const RETRYABLE_STATUS = new Set([408, 429, 502, 503, 504])

/** 退避参数。 */
const BACKOFF_BASE_MS = 500
const BACKOFF_MAX_MS = 16000
const MAX_ATTEMPTS = 4

/** 日志中绝不出现的字段(防御性脱敏)。 */
const SECRET_HEADERS = new Set(['authorization', 'x-github-token', 'token'])

/** 统一 GitHub 错误:含 gh/REST 原始摘要与指引,message 不出现在日志敏感字段上。 */
export class GitHubApiError extends Error {
  /**
   * @param {object} opts
   * @param {string} opts.method - HTTP 方法(大写)。
   * @param {string} opts.path - API 路径(含 query)。
   * @param {number|string|undefined} [opts.status] - HTTP 状态或 gh 退出码。
   * @param {string} [opts.kind] - gh | rest | auth。
   * @param {string} [opts.raw] - gh stderr / REST body 的原始摘要(截断)。
   * @param {string} [opts.guidance] - 附加指引(如 AUTH_GUIDANCE)。
   */
  constructor({ method, path, status, kind = 'rest', raw = '', guidance = '' }) {
    const where = kind === 'gh' ? 'gh' : kind === 'auth' ? 'GitHub 认证' : 'GitHub API'
    const detail = raw ? ` — ${snip(raw, 400)}` : ''
    super(`${where} 调用失败:${method} ${path} → ${status ?? 'error'}${detail}${guidance ? ` (${guidance})` : ''}`)
    this.name = 'GitHubApiError'
    this.kind = kind
    this.status = status
    this.method = method
    this.path = path
    this.raw = raw
    this.guidance = guidance
  }
}

/** 认证失败(写操作无凭据 / 凭据无效)。message 已含唯一指引。 */
export class GitHubAuthError extends GitHubApiError {
  constructor({ method, path, reason = '' }) {
    super({ method, path, status: 'auth', kind: 'auth', raw: reason, guidance: AUTH_GUIDANCE })
    this.name = 'GitHubAuthError'
  }
}

/** 截断字符串(错误摘要用)。 */
function snip(text, max) {
  const s = String(text ?? '').trim()
  return s.length > max ? `${s.slice(0, max)}…` : s
}

/** jitter 退避延迟(毫秒)。 */
export function backoffDelay(attempt, baseMs = BACKOFF_BASE_MS) {
  const exp = Math.min(baseMs * 2 ** (attempt - 1), BACKOFF_MAX_MS)
  return Math.round(exp + Math.random() * Math.min(baseMs, 250))
}

/** signal 可中断的 sleep。 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) return reject(abortError())
    const t = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort)
      resolve()
    }, ms)
    const onAbort = () => {
      clearTimeout(t)
      reject(abortError())
    }
    signal?.addEventListener('abort', onAbort, { once: true })
  })
}

function abortError() {
  const e = new Error('harness-github: 请求被取消')
  e.name = 'AbortError'
  return e
}

/**
 * 运行一个本地进程(gh / git / 任意 CLI),收集 stdout/stderr。
 * 供传输层调用 gh,也供 github_pr_prepare 在本地仓库执行 git/gh。
 * @param {string} cmd - 可执行文件。
 * @param {string[]} args - 参数数组(不经 shell,杜绝注入)。
 * @param {{ cwd?: string, signal?: AbortSignal, maxBuffer?: number, env?: NodeJS.ProcessEnv }} [opts]
 * @returns {Promise<{ code: number, stdout: string, stderr: string, signal?: NodeJS.Signals }>}
 */
export function runProcess(cmd, args = [], opts = {}) {
  const { cwd, signal, maxBuffer = 16 * 1024 * 1024, env = process.env } = opts
  return new Promise((resolve) => {
    const child = spawn(cmd, args, {
      cwd,
      env,
      stdio: ['ignore', 'pipe', 'pipe'],
      maxBuffer,
    })
    let stdout = ''
    let stderr = ''
    let terminatedBy = undefined
    child.stdout.on('data', (chunk) => { stdout += chunk })
    child.stderr.on('data', (chunk) => { stderr += chunk })
    child.on('error', (err) => {
      // cmd 不存在(ENOENT)等 —— 视为失败,code 置 -1
      resolve({ code: -1, stdout, stderr: `无法启动 ${cmd}: ${err.message}`, signal: terminatedBy })
    })
    child.on('close', (code, sig) => {
      resolve({ code: code ?? -1, stdout, stderr, signal: terminatedBy ?? sig })
    })
    if (signal) {
      if (signal.aborted) {
        terminatedBy = 'SIGTERM'
        child.kill('SIGTERM')
      } else {
        signal.addEventListener('abort', () => {
          terminatedBy = 'SIGTERM'
          child.kill('SIGTERM')
        }, { once: true })
      }
    }
  })
}

/**
 * 创建 GitHub 传输客户端。
 * @param {object} opts
 * @param {object} [opts.config] - 插件配置(apiBaseUrl 等)。
 * @param {{ debug?: Function, warn?: Function, info?: Function, error?: Function }} [opts.logger]
 * @param {(ref: string) => Promise<{ value: string, source?: string } | undefined>} [opts.resolveCredential]
 *   - 每次操作重新解析;凭据库缺失时传 undefined。
 * @param {{ fetch?: typeof fetch, spawn?: typeof spawn }} [opts.deps] - 测试注入点。
 */
export function createGitHubClient(opts = {}) {
  return new GitHubClient(opts)
}

class GitHubClient {
  #config
  #logger
  #resolveCredential
  #fetch
  #spawn
  #ghState = { checked: false, available: false, authed: false }

  constructor(opts) {
    this.#config = { apiBaseUrl: DEFAULT_API_BASE, ...(opts.config ?? {}) }
    this.#logger = opts.logger
    this.#resolveCredential = opts.resolveCredential
    this.#fetch = opts.deps?.fetch ?? globalThis.fetch
    this.#spawn = opts.deps?.spawn ?? spawn
  }

  #log(level, ...args) {
    const fn = this.#logger?.[level]
    if (typeof fn === 'function') {
      try { fn(...args.map((a) => redact(a))) } catch { /* logger 自身失败不影响调用 */ }
    }
  }

  /** gh 是否可用(缓存:gh --version)。 */
  async ghAvailable() {
    if (!this.#ghState.checked) {
      const r = await this.#spawnProcess('gh', ['--version'])
      this.#ghState.available = r.code === 0
      this.#ghState.checked = true
      this.#log('debug', `harness-github: gh 可用 = ${this.#ghState.available}`)
    }
    return this.#ghState.available
  }

  /** gh 是否已登录(缓存;检测到认证失效时由调用方置回未登录)。 */
  async ghAuthed() {
    if (!(await this.ghAvailable())) return false
    if (!this.#ghState.authed) {
      const r = await this.#spawnProcess('gh', ['auth', 'status'])
      this.#ghState.authed = r.code === 0
      this.#log('debug', `harness-github: gh 已登录 = ${this.#ghState.authed}`)
    }
    return this.#ghState.authed
  }

  /**
   * 解析当前可用的 token(env → 凭据库),每次操作重新解析。
   * @returns {Promise<string | undefined>}
   */
  async getToken() {
    const fromEnv = process.env.GITHUB_TOKEN || process.env.GH_TOKEN || undefined
    if (fromEnv) return fromEnv
    if (typeof this.#resolveCredential === 'function') {
      try {
        const resolved = await this.#resolveCredential('GITHUB_TOKEN')
        return resolved?.value || undefined
      } catch (err) {
        this.#log('warn', `harness-github: 凭据库解析失败: ${err?.message ?? err}`)
        return undefined
      }
    }
    return undefined
  }

  /**
   * 写操作前置检查:gh 已登录或有 token,否则抛 GitHubAuthError。
   */
  async assertCanWrite() {
    if (await this.ghAuthed()) return true
    if (await this.getToken()) return true
    throw new GitHubAuthError({
      method: 'write',
      path: 'GitHub',
      reason: '需要写权限但没有可用凭据(gh 未登录且无 GITHUB_TOKEN)。',
    })
  }

  /**
   * 统一请求入口:gh CLI 优先 → REST 回退。
   * @param {string} method - GET / POST / PUT / PATCH / DELETE。
   * @param {string} path - 如 `/repos/o/r/pulls`(可带 query)。
   * @param {object} [opts]
   * @param {object} [opts.query] - 追加的 query 参数。
   * @param {unknown} [opts.body] - JSON body。
   * @param {boolean} [opts.readonly] - 是否只读(决定匿名/写权限放行)。
   * @param {boolean} [opts.paginate] - 是否跨页聚合(仅数组响应)。
   * @param {AbortSignal} [opts.signal]
   * @returns {Promise<unknown>} 统一 JSON(或文本时返回 { _text: string })。
   */
  async request(method, path, opts = {}) {
    const { query, body, readonly = true, paginate = false, signal } = opts
    const full = appendQuery(path, query)
    if (!readonly) await this.assertCanWrite()

    if (await this.ghAuthed()) {
      try {
        return await this.#ghRequest(method, full, { body, paginate, signal, readonly })
      } catch (err) {
        // gh 认证中途失效(401)→ 置回未登录,本次改走 REST
        if (err instanceof GitHubApiError && Number(err.status) === 401) {
          this.#ghState.authed = false
          this.#log('warn', `harness-github: gh 调用 401,回退 REST: ${err.message}`)
        } else {
          throw err
        }
      }
    } else {
      this.#log('debug', 'harness-github: 使用 REST 路径(gh 不可用或未登录)')
    }

    const token = await this.getToken()
    if (!readonly && !token) {
      // assertCanWrite 后 token 消失的竞态兜底
      throw new GitHubAuthError({
        method,
        path: full,
        reason: '写操作需要凭据(token 解析为空)。',
      })
    }
    return this.#restRequest(method, full, { body, token, paginate, signal })
  }

  /** gh 模式:gh api 与 REST 同路径,输出即 REST JSON。 */
  async #ghRequest(method, full, { body, paginate, signal, readonly }) {
    const ghPath = full.replace(/^\//, '')
    const args = ['api', ghPath]
    if (method !== 'GET') args.push('--method', method)
    if (paginate) args.push('--paginate')
    let stdin = undefined
    if (body !== undefined && method !== 'GET') {
      stdin = JSON.stringify(body)
      args.push('--input', '-')
    }
    const r = await this.#spawnProcess('gh', args, { signal, stdin })
    if (r.code === 0) {
      const out = r.stdout.trim()
      if (!out) return null
      try {
        return JSON.parse(out)
      } catch {
        // 非 JSON 响应(如日志文本)
        return { _text: out }
      }
    }
    const stderr = r.stderr.trim() || r.stdout.trim()
    const m = /HTTP\s+(\d{3})/.exec(stderr)
    const status = m ? Number(m[1]) : undefined
    throw new GitHubApiError({
      method,
      path: full,
      status: status ?? r.code,
      kind: 'gh',
      raw: stderr,
    })
  }

  /** REST 模式:fetch + Bearer token + 指数退避。 */
  async #restRequest(method, full, { body, token, paginate, signal }) {
    const url = `${this.#config.apiBaseUrl}${full}`
    const headers = {
      Accept: 'application/vnd.github+json',
      'X-GitHub-Api-Version': '2022-11-28',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
      ...(body !== undefined ? { 'Content-Type': 'application/json' } : {}),
    }
    const init = {
      method,
      headers,
      ...(body !== undefined ? { body: JSON.stringify(body) } : {}),
      signal,
    }

    const response = await this.#fetchWithRetry(url, init, signal)
    const isText = /text\/plain/.test(response.headers.get('content-type') ?? '')
    const raw = isText ? await response.text() : await response.text().catch(() => '')
    let data
    if (raw) {
      try { data = JSON.parse(raw) } catch { data = isText ? { _text: raw } : undefined }
    }
    if (!response.ok) {
      const message = data && typeof data === 'object' && 'message' in data
        ? String(data.message)
        : raw.slice(0, 400)
      const rateLimited = response.status === 403
        && (response.headers.get('x-ratelimit-remaining') === '0' || /rate limit/i.test(message))
      if (rateLimited) {
        throw new GitHubApiError({
          method,
          path: full,
          status: response.status,
          kind: 'rest',
          raw: `${message} (速率限制:匿名调用每小时约 60 次;登录 gh 或设置 GITHUB_TOKEN 可提升限额)`,
        })
      }
      throw new GitHubApiError({
        method,
        path: full,
        status: response.status,
        kind: 'rest',
        raw: message || `HTTP ${response.status}`,
      })
    }
    if (paginate && Array.isArray(data) && response.headers.get('link')) {
      const rest = await this.#paginateRest(url, data, response.headers.get('link'), init, signal)
      return rest
    }
    return data ?? null
  }

  /** fetch + 429/5xx 指数退避;网络错误在重试耗尽后转成 GitHubApiError。 */
  async #fetchWithRetry(url, init, signal) {
    let attempt = 0
    for (;;) {
      attempt += 1
      let response
      try {
        response = await this.#fetch(url, init)
      } catch (err) {
        if (signal?.aborted) throw abortError()
        const network = err instanceof TypeError || /fetch failed|ENOTFOUND|ECONNREFUSED/i.test(String(err?.message ?? err))
        if (network && attempt < MAX_ATTEMPTS) {
          await sleep(backoffDelay(attempt), signal)
          continue
        }
        throw new GitHubApiError({
          method: init.method ?? 'GET',
          path: url.replace(this.#config.apiBaseUrl, ''),
          status: 'network',
          kind: 'rest',
          raw: err?.message ?? String(err),
        })
      }
      if (RETRYABLE_STATUS.has(response.status) && attempt < MAX_ATTEMPTS) {
        const retryAfter = Number(response.headers.get('retry-after'))
        const delay = Number.isFinite(retryAfter) && retryAfter > 0
          ? Math.min(retryAfter * 1000, BACKOFF_MAX_MS)
          : backoffDelay(attempt)
        this.#log('warn', `harness-github: HTTP ${response.status} 重试(${attempt}/${MAX_ATTEMPTS}),${delay}ms 后`)
        await sleep(delay, signal)
        continue
      }
      return response
    }
  }

  /** 逐页聚合(Link rel=next)。 */
  async #paginateRest(firstUrl, firstData, linkHeader, init, signal) {
    const items = [...firstData]
    let nextUrl = parseNextLink(linkHeader)
    while (nextUrl) {
      const res = await this.#fetchWithRetry(nextUrl, init, signal)
      const text = await res.text().catch(() => '')
      let page
      try { page = JSON.parse(text) } catch { break }
      if (!res.ok) break
      if (!Array.isArray(page)) break
      items.push(...page)
      nextUrl = parseNextLink(res.headers.get('link'))
    }
    return items
  }

  /** 进程执行(gh 专用,含 stdin 支持)。 */
  #spawnProcess(cmd, args, { signal, stdin, cwd, env } = {}) {
    const child = this.#spawn(cmd, args, {
      cwd,
      env,
      stdio: stdin !== undefined ? ['pipe', 'pipe', 'pipe'] : ['ignore', 'pipe', 'pipe'],
    })
    return new Promise((resolve) => {
      let stdout = ''
      let stderr = ''
      let killed = false
      child.stdout?.on('data', (chunk) => { stdout += chunk })
      child.stderr?.on('data', (chunk) => { stderr += chunk })
      if (stdin !== undefined) {
        child.stdin?.on('error', () => undefined)
        child.stdin?.end(stdin)
      }
      child.on('error', (err) => {
        resolve({ code: -1, stdout, stderr: `无法启动 ${cmd}: ${err.message}`, killed })
      })
      child.on('close', (code, sig) => {
        resolve({ code: code ?? -1, stdout, stderr, killed: killed || sig === 'SIGTERM' })
      })
      if (signal) {
        if (signal.aborted) { killed = true; child.kill('SIGTERM') }
        else signal.addEventListener('abort', () => { killed = true; child.kill('SIGTERM') }, { once: true })
      }
    })
  }

  // ---- 以下为工具使用的语义化 API(全部经 request 统一路由) ----

  /** 仓库概览。 */
  repo(owner, repo, opts) {
    return this.request('GET', `/repos/${owner}/${repo}`, { readonly: true, ...opts })
  }

  /** 列 PR(pulls 列表接口;state=open/closed/all)。 */
  listPRs(owner, repo, { state = 'open', perPage = 30 } = {}, opts) {
    return this.request('GET', `/repos/${owner}/${repo}/pulls`, {
      query: { state, per_page: perPage, sort: 'updated', direction: 'desc' },
      readonly: true,
      ...opts,
    })
  }

  /** 单个 PR 详情。 */
  pr(owner, repo, number, opts) {
    return this.request('GET', `/repos/${owner}/${repo}/pulls/${number}`, { readonly: true, ...opts })
  }

  /** PR 文件变更。 */
  prFiles(owner, repo, number, opts) {
    return this.request('GET', `/repos/${owner}/${repo}/pulls/${number}/files`, {
      query: { per_page: 100 },
      readonly: true,
      ...opts,
    })
  }

  /** PR/issue 的 issue 评论(gh pr comment 的底层)。 */
  prIssueComments(owner, repo, number, opts) {
    return this.request('GET', `/repos/${owner}/${repo}/issues/${number}/comments`, {
      query: { per_page: 100 },
      readonly: true,
      ...opts,
    })
  }

  /** PR 的行内 review 评论(threads)。 */
  prReviewComments(owner, repo, number, opts) {
    return this.request('GET', `/repos/${owner}/${repo}/pulls/${number}/comments`, {
      query: { per_page: 100 },
      readonly: true,
      ...opts,
    })
  }

  /** PR 的 review 提交记录。 */
  prReviews(owner, repo, number, opts) {
    return this.request('GET', `/repos/${owner}/${repo}/pulls/${number}/reviews`, {
      query: { per_page: 100 },
      readonly: true,
      ...opts,
    })
  }

  /** 检查 PR 的 checks:statusCheckRollup + Actions run 列表。 */
  async prChecks(owner, repo, number, opts) {
    const p = await this.pr(owner, repo, number, opts)
    const sha = p?.head?.sha
    if (!sha) return { sha: undefined, statusChecks: [], runs: [] }
    const checkRuns = await this.request('GET', `/repos/${owner}/${repo}/commits/${sha}/check-runs`, {
      query: { per_page: 100 },
      readonly: true,
      ...opts,
    }).catch(() => ({ check_runs: [] }))
    const runs = await this.request('GET', `/repos/${owner}/${repo}/actions/runs`, {
      query: { head_sha: sha, per_page: 30 },
      readonly: true,
      ...opts,
    }).catch(() => ({ workflow_runs: [] }))
    return {
      sha,
      head_sha: sha,
      statusChecks: Array.isArray(checkRuns?.check_runs) ? checkRuns.check_runs : [],
      // statusCheckRollup:按结论聚合,供模型快速判断
      rollup: rollupChecks(Array.isArray(checkRuns?.check_runs) ? checkRuns.check_runs : []),
      runs: Array.isArray(runs?.workflow_runs) ? runs.workflow_runs : [],
    }
  }

  /** 单个 workflow run 详情 + jobs(含步骤结论)。 */
  async workflowRun(owner, repo, runId, opts) {
    const run = await this.request('GET', `/repos/${owner}/${repo}/actions/runs/${runId}`, {
      readonly: true,
      ...opts,
    })
    const jobs = await this.request('GET', `/repos/${owner}/${repo}/actions/runs/${runId}/jobs`, {
      query: { per_page: 100 },
      readonly: true,
      ...opts,
    }).catch(() => ({ jobs: [] }))
    return { run, jobs: Array.isArray(jobs?.jobs) ? jobs.jobs : [] }
  }

  /**
   * 失败步骤的关键日志行(等效 `gh run view --log-failed`)。
   * 取所有失败 job 的日志,REST 用 jobs/{id}/logs 原始文本。
   */
  async workflowRunLogs(owner, repo, runId, opts) {
    const { run, jobs } = await this.workflowRun(owner, repo, runId, opts)
    const failedJobs = jobs.filter((j) => j.conclusion === 'failure' || j.conclusion === 'timed_out')
    const results = []
    for (const job of failedJobs) {
      const failedSteps = (job.steps ?? []).filter((s) =>
        s.conclusion === 'failure' || s.conclusion === 'timed_out')
      let log = ''
      try {
        const res = await this.request('GET', `/repos/${owner}/${repo}/actions/jobs/${job.id}/logs`, {
          readonly: true,
          ...opts,
        })
        log = typeof res === 'object' && res !== null && '_text' in res ? String(res._text) : ''
      } catch { log = '' }
      results.push({
        jobId: job.id,
        jobName: job.name,
        jobUrl: job.html_url ?? null,
        failedSteps: failedSteps.map((s) => ({ name: s.name, conclusion: s.conclusion })),
        log: excerptLog(log, failedSteps.map((s) => s.name)),
      })
    }
    return {
      runId,
      runName: run?.name ?? null,
      runUrl: run?.html_url ?? null,
      runStatus: run?.status ?? null,
      runConclusion: run?.conclusion ?? null,
      failedJobs: results,
    }
  }

  /** 列 issue(issues 接口,自动排除 PR)。 */
  listIssues(owner, repo, { state = 'open', labels, assignee, perPage = 30 } = {}, opts) {
    return this.request('GET', `/repos/${owner}/${repo}/issues`, {
      query: {
        state,
        per_page: perPage,
        sort: 'updated',
        direction: 'desc',
        ...(labels ? { labels } : {}),
        ...(assignee ? { assignee } : {}),
      },
      readonly: true,
      ...opts,
    })
  }

  /** 单个 issue 详情。 */
  issue(owner, repo, number, opts) {
    return this.request('GET', `/repos/${owner}/${repo}/issues/${number}`, { readonly: true, ...opts })
  }

  /** issue 评论。 */
  issueComments(owner, repo, number, opts) {
    return this.request('GET', `/repos/${owner}/${repo}/issues/${number}/comments`, {
      query: { per_page: 100 },
      readonly: true,
      ...opts,
    })
  }

  /** 搜索(type: issues/repositories/code/commits 等)。 */
  search(type, { q, perPage = 30 } = {}, opts) {
    return this.request('GET', `/search/${type}`, {
      query: { q, per_page: perPage },
      readonly: true,
      ...opts,
    })
  }

  /** 最近发布。 */
  releases(owner, repo, { perPage = 30 } = {}, opts) {
    return this.request('GET', `/repos/${owner}/${repo}/releases`, {
      query: { per_page: perPage },
      readonly: true,
      ...opts,
    })
  }

  // ---- 写操作(全部经 request 的 readonly=false 触发 assertCanWrite) ----

  /** 按 head 分支查找已存在的 open PR(防重复)。 */
  listPRsByHead(owner, repo, head, opts) {
    const ownerHead = head.includes(':') ? head : `${owner}:${head}`
    return this.request('GET', `/repos/${owner}/${repo}/pulls`, {
      query: { state: 'open', head: ownerHead, per_page: 10 },
      readonly: true,
      ...opts,
    })
  }

  /** 建 PR。 */
  createPR(owner, repo, { title, body, base, head, draft = false }, opts) {
    return this.request('POST', `/repos/${owner}/${repo}/pulls`, {
      body: { title, body, base, head, draft },
      readonly: false,
      ...opts,
    })
  }

  /** 评论 PR/issue(issue comments 端点)。 */
  commentIssue(owner, repo, number, commentBody, opts) {
    return this.request('POST', `/repos/${owner}/${repo}/issues/${number}/comments`, {
      body: { body: commentBody },
      readonly: false,
      ...opts,
    })
  }

  /** 提交 PR review(approve/comment/request-changes,可带行内评论)。 */
  submitReview(owner, repo, number, { event, body, comments }, opts) {
    return this.request('POST', `/repos/${owner}/${repo}/pulls/${number}/reviews`, {
      body: {
        body,
        event,
        ...(Array.isArray(comments) && comments.length > 0 ? { comments } : {}),
      },
      readonly: false,
      ...opts,
    })
  }

  /** 合并 PR(merge/squash/rebase),可选删除源分支。 */
  async mergePR(owner, repo, number, { method = 'merge', deleteBranch = false }, opts) {
    const result = await this.request('PUT', `/repos/${owner}/${repo}/pulls/${number}/merge`, {
      body: { merge_method: method },
      readonly: false,
      ...opts,
    })
    if (deleteBranch && result?.merged) {
      const branch = (await this.pr(owner, repo, number, opts))?.head?.ref
      if (branch) {
        await this.request('DELETE', `/repos/${owner}/${repo}/git/refs/heads/${branch}`, {
          readonly: false,
          ...opts,
        }).catch(() => undefined) // 删除失败不阻断合并结果
      }
    }
    return result
  }

  /** 建 issue。 */
  createIssue(owner, repo, { title, body, labels, assignees }, opts) {
    return this.request('POST', `/repos/${owner}/${repo}/issues`, {
      body: {
        title,
        ...(body !== undefined ? { body } : {}),
        ...(Array.isArray(labels) && labels.length > 0 ? { labels } : {}),
        ...(Array.isArray(assignees) && assignees.length > 0 ? { assignees } : {}),
      },
      readonly: false,
      ...opts,
    })
  }

  /** 关闭 issue(可先评论原因)。 */
  async closeIssue(owner, repo, number, { comment } = {}, opts) {
    if (comment) {
      await this.commentIssue(owner, repo, number, comment, opts)
    }
    return this.request('PATCH', `/repos/${owner}/${repo}/issues/${number}`, {
      body: { state: 'closed' },
      readonly: false,
      ...opts,
    })
  }
}

/** 拼接 query 参数到 path。 */
function appendQuery(path, query) {
  if (!query || Object.keys(query).length === 0) return path
  const qs = new URLSearchParams()
  for (const [k, v] of Object.entries(query)) {
    if (v === undefined || v === null || v === '') continue
    qs.set(k, String(v))
  }
  const q = qs.toString()
  if (!q) return path
  return path.includes('?') ? `${path}&${q}` : `${path}?${q}`
}

/** 聚合 check-run 结论(statusCheckRollup)。 */
export function rollupChecks(checkRuns) {
  const counts = { success: 0, failure: 0, neutral: 0, cancelled: 0, skipped: 0, timed_out: 0, action_required: 0, in_progress: 0, queued: 0, stale: 0, unknown: 0 }
  for (const cr of checkRuns) {
    const key = cr.conclusion ?? cr.status ?? 'unknown'
    counts[key] = (counts[key] ?? 0) + 1
  }
  return counts
}

/** 从链接头解析下一页 URL。 */
export function parseNextLink(linkHeader) {
  if (!linkHeader) return undefined
  for (const part of linkHeader.split(',')) {
    const [urlPart, relPart] = part.split(';')
    if (/rel="?next"?/.test(relPart ?? '')) {
      return urlPart?.trim().replace(/^<|>$/g, '')
    }
  }
  return undefined
}

/** 从 raw log 提取失败 step 的关键行。 */
export function excerptLog(rawLog, failedStepNames) {
  if (!rawLog) return []
  const lines = String(rawLog).split('\n')
  // 按 ##[group] 分段,优先匹配失败步骤名
  const blocks = []
  let current = null
  for (const line of lines) {
    const m = /^##\[group\](.*)$/.exec(line)
    if (m) {
      if (current) blocks.push(current)
      current = { header: m[1].trim(), lines: [] }
    } else if (current) {
      current.lines.push(line)
    } else {
      // 未分段的行,并入一个虚拟块(便于取尾部)
      if (blocks.length === 0) blocks.push({ header: '', lines: [] })
      blocks[0].lines.push(line)
    }
  }
  if (current) blocks.push(current)
  const wanted = failedStepNames ?? []
  const picked = blocks.filter((b) => wanted.some((w) => b.header.includes(w)))
  const source = picked.length > 0 ? picked : blocks
  const tail = []
  for (const b of source) {
    tail.push(`## ${b.header || '(log)'}`)
    tail.push(...b.lines.slice(-40))
  }
  const interesting = lines.filter((l) => /error|failed|fatal|exception|^error:|cannot|unable to/i.test(l))
  const merged = [...tail, '## (关键匹配行)', ...interesting.slice(0, 40)]
  return merged.slice(-120)
}

/** 防御性脱敏(日志用)。 */
function redact(value) {
  if (typeof value !== 'string') return value
  return value.replace(/(Bearer\s+)[A-Za-z0-9_\-.]{8,}/g, '$1***')
    .replace(/(ghp_[A-Za-z0-9]+|github_pat_[A-Za-z0-9_]+)/g, '***')
}"
    },
    {
      "path": "lib/tools-read.js",
      "content": "/**
 * harness-github —— 只读工具定义(10 个,免审批)。
 *
 * 每个工具:结构化 JSON(value,由 output.schema 约束)+ render 转易读文本;
 * description 末尾附"对应 gh 命令",供模型在 gh 已登录时直接走 CLI 更快完成单次查询。
 *
 * execute 签名:(args, exec) → Promise<value>;exec.signal 透传给传输层实现取消。
 */

// ---------- 渲染辅助 ----------

/** 时间差的可读描述(渲染用)。 */
export function ago(iso) {
  if (!iso) return ''
  const t = new Date(iso).getTime()
  if (!Number.isFinite(t)) return iso
  const diff = Date.now() - t
  const sec = Math.floor(diff / 1000)
  if (sec < 60) return `${sec}s 前`
  const min = Math.floor(sec / 60)
  if (min < 60) return `${min}m 前`
  const hour = Math.floor(min / 60)
  if (hour < 24) return `${hour}h 前`
  const day = Math.floor(hour / 24)
  if (day < 30) return `${day}d 前`
  const month = Math.floor(day / 30)
  if (month < 12) return `${month}mo 前`
  return `${Math.floor(month / 12)}y 前`
}

/** 渲染用的文本块快捷方式。 */
function text(value) {
  return [{ type: 'text', text: String(value) }]
}

/** 输出 schema 统一 object(关闭额外属性,逐字段 required)。 */
function obj(properties) {
  return { type: 'object', additionalProperties: false, properties }
}

/** 把 GH 标签数组转成逗号串。 */
function labelsText(labels) {
  if (!Array.isArray(labels) || labels.length === 0) return '(无标签)'
  return labels.map((l) => (typeof l === 'string' ? l : l.name)).join(', ')
}

/** 公共:把 API 字段映射为工具输出字段。 */
function mapIssue(i) {
  return {
    number: i.number,
    title: i.title,
    state: i.state,
    author: i.user?.login ?? null,
    labels: (i.labels ?? []).map((l) => (typeof l === 'string' ? l : l.name)),
    assignees: (i.assignees ?? []).map((a) => a.login),
    comments: i.comments ?? 0,
    createdAt: i.created_at ?? null,
    updatedAt: i.updated_at ?? null,
    url: i.html_url ?? null,
  }
}

function mapComment(c) {
  return {
    id: c.id,
    author: c.user?.login ?? null,
    createdAt: c.created_at ?? null,
    body: c.body ?? '',
  }
}

function mapReview(r) {
  return {
    id: r.id,
    author: r.user?.login ?? null,
    state: r.state ?? null,
    submittedAt: r.submitted_at ?? null,
    body: r.body ?? '',
  }
}

function mapReviewComment(c) {
  return {
    id: c.id,
    path: c.path ?? null,
    line: c.line ?? c.original_line ?? 0,
    side: c.side ?? null,
    author: c.user?.login ?? null,
    createdAt: c.created_at ?? null,
    body: c.body ?? '',
    inReplyTo: c.in_reply_to_id ?? null,
    url: c.html_url ?? null,
  }
}

/**
