          if (changes.length) lines.push(`⛔ 请求变更:${changes.map((r) => `@${r.author}`).join('、')}`)
          if (approves.length) lines.push(`✅ 已批准:${approves.map((r) => `@${r.author}`).join('、')}`)
          for (const r of v.reviews) {
            if (r.body) lines.push(`--- review by @${r.author}(${r.state}) ${ago(r.submittedAt)}\n${r.body}`)
          }
          const unresolved = v.threads.filter((t) => !t.comments.some((c) => /resolved|done/i.test(c.body)))
          lines.push('', `行内评论线程:${v.threads.length} 个${unresolved.length < v.threads.length ? `(${v.threads.length - unresolved.length} 已标记解决)` : ''}`)
          for (const t of unresolved) {
            lines.push(`## ${t.path}:${t.line}(${t.side || 'RIGHT'})`)
            for (const c of t.comments) {
              lines.push(`- @${c.author} ${ago(c.createdAt)}:${c.body ? ` ${c.body}` : '(空)'}`)
            }
          }
          return text(lines.join('\n'))
        },
