      async execute(args, exec) {
        const [owner, repo] = splitRepo(args.repo)
        const signal = { signal: exec.signal }
        const [reviews, comments] = await Promise.all([
          client.prReviews(owner, repo, args.number, signal),
          client.prReviewComments(owner, repo, args.number, signal),
        ])
        // 按 in_reply_to 归并为线程:每条评论挂到它的根评论(回复链顶端)下
        const byId = new Map()
        for (const c of comments ?? []) byId.set(c.id, mapReviewComment(c))
        const rootOf = new Map()
        const rootId = (id) => {
          if (rootOf.has(id)) return rootOf.get(id)
          const c = byId.get(id)
          const rid = c && c.inReplyTo && byId.has(c.inReplyTo) ? rootId(c.inReplyTo) : id
          rootOf.set(id, rid)
          return rid
        }
        const grouped = new Map()
        for (const c of comments ?? []) {
          const mc = mapReviewComment(c)
          const rid = rootId(c.id)
          if (!grouped.has(rid)) grouped.set(rid, [])
          grouped.get(rid).push(mc)
        }
        return {
          reviews: (reviews ?? []).map(mapReview),
          threads: [...grouped.entries()].map(([, list]) => {
            const head = list[0]
            return {
              id: head.id,
              path: head.path ?? '',
              line: head.line ?? 0,
              side: head.side ?? 'RIGHT',
              comments: list.map((c) => ({
                id: c.id,
                author: c.author,
                createdAt: c.createdAt,
                body: c.body,
                url: c.url,
              })),
            }
          }),
        }
      },
    },
