}

// ---------- 内部辅助 ----------

/** owner/repo 分隔(容错:接受带空格/首尾斜杠)。 */
export function splitRepo(repo) {
  const parts = String(repo ?? '').trim().replace(/\/+$/, '').split('/')
  if (parts.length !== 2 || !parts[0] || !parts[1]) {
    throw new Error(`repo 参数格式应为 owner/repo,收到:${JSON.stringify(repo)}`)
  }
  return parts
}

function summarizeReviews(states) {
  if (states.length === 0) return '暂无 review'
  const counts = {}
  for (const s of states) counts[s] = (counts[s] ?? 0) + 1
  const parts = []
  if (counts.APPROVED) parts.push(`${counts.APPROVED} 个批准`)
  if (counts.CHANGES_REQUESTED) parts.push(`${counts.CHANGES_REQUESTED} 个请求变更`)
  if (counts.COMMENTED) parts.push(`${counts.COMMENTED} 个评论`)
  if (counts.DISMISSED) parts.push(`${counts.DISMISSED} 个已撤销`)
  return parts.join('、') || states.join(',')
}"
