      "path": "lib/tools-write.js",
      "content": "/**
 * harness-github —— 写工具定义(7 个写操作 + 1 个本地流程)+ requestApproval 审批封装。
 *
 * 写操作铁律:任何远程改动前统一过 requestApproval(ctx, exec, reason)——
 *   - approval 服务可用:返回 'allowed-once' 才放行;rejected/cancelled/unavailable 一律拒绝;
 *   - approval 服务缺失或 exec.agent 为空 → 直接拒绝(绝不静默放行);
 *   - 拒绝发生在任何写请求发出之前 → 零副作用。
 * 只读前置(如查已有 PR、本地 git 状态)发生在审批之前,不产生副作用。
 */
import { runProcess } from './github.js'
import { splitRepo } from './tools-read.js'
import { AUTH_GUIDANCE } from './github.js'

// ---------- 渲染辅助 ----------

function text(value) {
  return [{ type: 'text', text: String(value) }]
}

function obj(properties) {
  return { type: 'object', additionalProperties: false, properties }
}

// ---------- 审批封装 ----------

/**
 * 审批封装:所有写工具执行前调用。
 * @param {import('@deepseek-ai/cordis').Context} ctx - Cordis 上下文。
 * @param {import('@deepseek-ai/dsh-tools').ToolRunContext} exec - 工具执行上下文(含 agent/signal/callId)。
 * @param {string} reason - 给用户看的中文审批原因(含具体对象)。
 * @throws 审批缺失 / agent 缺失 / 非 allowed-once 时抛出(无任何副作用)。
 */
export async function requestApproval(ctx, exec, reason) {
  const approval = ctx.get('approval')
  if (!approval || typeof approval.request !== 'function') {
    throw new Error(
      `[harness-github] 写操作未获准:审批服务不可用(approval 服务缺失),已拒绝执行「${reason}」。` +
      `如需写操作,请确保宿主加载了 approval 服务。${AUTH_GUIDANCE}`,
    )
  }
  if (!exec?.agent) {
    throw new Error(
      `[harness-github] 写操作未获准:缺少 agent 上下文,无法发起人工审批,已拒绝执行「${reason}」。`,
    )
  }
  const outcome = await approval.request({
    agent: exec.agent,
    toolName: exec.name,
    callId: exec.callId,
    reason: `[harness-github] ${reason}`,
    signal: exec.signal,
  })
  if (outcome !== 'allowed-once') {
    const why = outcome === 'rejected'
      ? '已被拒绝'
      : outcome === 'cancelled'
        ? '已取消'
        : '不可用(fail-closed)'
    throw new Error(`[harness-github] 写操作未获准:审批${why},未执行任何改动(「${reason}」)。`)
  }
  return true
}

// ---------- 本地仓库辅助(github_pr_prepare 用) ----------

async function git(dir, args, opts = {}) {
  const r = await runProcess('git', args, { cwd: dir, signal: opts.signal })
  return r
}

function gitOut(r, maxLines = 20) {
  const s = (r.stdout ?? '').trim()
  if (!s) return ''
  return s.split('\n').slice(0, maxLines).map((l) => `  ${l}`).join('\n')
}

/** 解析工作目录:args.dir → exec.agent session cwd → process.cwd()。 */
function resolveDir(args, exec) {
  const dir = args.dir ?? exec?.agent?.session?.header?.cwd ?? process.cwd()
  return String(dir)
}

/**
