            return text(`已创建 PR #${v.number}:${v.title}(${v.headRef} → ${v.baseRef})${v.draft ? ' [draft]' : ''}\n${v.url}`)
          }
          return text(`该分支已有 open PR #${v.number}:${v.title}(未重复创建)\n${v.url}`)
        },
      },
      async execute(args, exec) {
        const [owner, repo] = splitRepo(args.repo)
        // 只读前置:查已有 open PR(防重复,无副作用)
        const existing = await client.listPRsByHead(owner, repo, args.head, { signal: exec.signal })
        if (Array.isArray(existing) && existing.length > 0) {
          const p = existing[0]
          return {
            created: false,
            existingNumber: p.number,
            number: p.number,
            url: p.html_url ?? '',
            title: p.title ?? '',
            baseRef: p.base?.ref ?? '',
            headRef: p.head?.ref ?? '',
            draft: !!p.draft,
          }
        }
        const base = args.base ?? (await client.repo(owner, repo, { signal: exec.signal })).default_branch ?? 'main'
        const reason = `创建 PR:${owner}/${repo} 「${args.title}」(${args.head} → ${base})${args.draft ? ' [draft]' : ''}`
        await requestApproval(ctx, exec, reason)
        const created = await client.createPR(owner, repo, {
          title: args.title,
          body: args.body,
          base,
          head: args.head,
          draft: !!args.draft,
        }, { signal: exec.signal })
        return {
          created: true,
          existingNumber: 0,
          number: created.number,
          url: created.html_url ?? '',
          title: created.title ?? '',
          baseRef: created.base?.ref ?? base,
          headRef: created.head?.ref ?? args.head,
          draft: !!created.draft,
        }
      },
    },

