    // 7. github_issue_close
    {
      name: 'github_issue_close',
      description:
        '关闭 issue(需人工审批),可附关闭原因评论(先评论再关闭)。对应 gh 命令:gh issue close <number> --repo <owner>/<repo> [--comment "<reason>"]',
      parameters: {
        repo: { type: 'string', required: true, description: '仓库,格式 owner/repo。' },
        number: { type: 'integer', required: true, description: 'issue 编号。' },
        comment: { type: 'string', description: '可选:关闭前的评论(说明原因,如已修复/重复/计划外)。' },
      },
      output: {
