        }
      },
    },

    // 8. github_pr_prepare(本地流程:对齐 Codex 的 yeet)
    {
      name: 'github_pr_prepare',
      description:
        '准备本地代码变更并进入发 PR 流程(需人工审批):检查本地分支领先/推送状态;工作区有未提交改动时给出 git 指引' +
        '(或 autoCommit 自动提交);需要时推送到远端;检测 head 分支已有 open PR 防重复,没有则创建 PR。' +
        '对应 gh 命令:git status && git push && gh pr create --repo <owner>/<repo> --title "<title>" --base <base> --head "$(git branch --show-current)"',
      parameters: {
        repo: { type: 'string', required: true, description: '目标仓库,格式 owner/repo。' },
        dir: { type: 'string', description: '本地仓库目录;默认取会话工作目录(exec.agent.session.header.cwd),取不到时报错提示传 dir。' },
        base: { type: 'string', description: 'PR 目标分支,默认仓库默认分支。' },
        title: { type: 'string', description: 'PR 标题,默认「<branch>: 变更」;仅 createPR=true 时使用。' },
        body: { type: 'string', description: 'PR 描述;仅 createPR=true 时使用。' },
        autoCommit: { type: 'boolean', default: false, description: '工作区有未提交改动时,自动 git add -A 并提交(commitMessage 必填);false 则只给指引不落盘。' },
        commitMessage: { type: 'string', description: 'autoCommit=true 且工作区有改动时的提交信息(必填)。' },
        createPR: { type: 'boolean', default: true, description: '推送后自动创建 PR(需审批);false 则只推送。' },
      },
      output: {
        schema: obj({
          dir: { type: 'string', required: true },
          branch: { type: 'string', required: true },
          upstream: { type: 'string', required: true },
          ahead: { type: 'integer', required: true },
          behind: { type: 'integer', required: true },
          unpushed: { type: 'integer', required: true },
          dirty: { type: 'boolean', required: true },
          action: {
            type: 'string',
            enum: ['created', 'existing', 'pushed', 'guidance'],
            required: true,
          },
          prNumber: { type: 'integer', required: true },
          prUrl: { type: 'string', required: true },
          guidance: { type: 'string', required: true },
        }),
        render: (_args, v) => {
          const lines = [`本地仓库:${v.dir} | 分支:${v.branch}`, `上游:${v.upstream || '(未设置)'} | ahead ${v.ahead} / behind ${v.behind} | 未推送 ${v.unpushed} | 工作区${v.dirty ? '有未提交改动' : '干净'}`]
          if (v.action === 'created') lines.push(`✅ 已推送并创建 PR #${v.prNumber}:${v.prUrl}`)
          else if (v.action === 'existing') lines.push(`ℹ️ 该分支已有 open PR #${v.prNumber}:${v.prUrl},未重复创建`)
          else if (v.action === 'pushed') lines.push(`✅ 已推送(未创建 PR,createPR=false)`)
          else if (v.action === 'guidance') lines.push(`⏳ 未执行任何写操作,按以下指引手动操作:`)
          if (v.guidance) lines.push('', v.guidance)
          return text(lines.join('\n'))
        },
      },
      async execute(args, exec) {
        const [owner, repo] = splitRepo(args.repo)
        const dir = resolveDir(args, exec)
        // 1) 只读:检查是否为 git 仓库并解析当前分支
        const check = await git(dir, ['rev-parse', '--is-inside-work-tree'], { signal: exec.signal })
        if (check.code !== 0) {
          throw new Error(`[harness-github] ${dir} 不是 git 工作区。请传 dir 指向本地仓库,或先 git init/克隆。`)
        }
        const branch = (await git(dir, ['rev-parse', '--abbrev-ref', 'HEAD'], { signal: exec.signal })).stdout.trim()

        // 2) 工作区未提交改动:autoCommit 才动本地盘(仍属本地,不进审批;出错即停,无副作用残留由 git 保证)
        let dirty = (await git(dir, ['status', '--porcelain'], { signal: exec.signal })).stdout.trim().length > 0
        const guidanceParts = []
        if (dirty) {
          if (args.autoCommit) {
            if (!args.commitMessage) {
              throw new Error('[harness-github] autoCommit=true 但未提供 commitMessage,已停止(未做任何改动)。请先提交或提供提交信息。')
            }
            const add = await git(dir, ['add', '-A'], { signal: exec.signal })
            if (add.code !== 0) throw new Error(`[harness-github] git add 失败:${add.stderr.trim()}`)
            const commit = await git(dir, ['commit', '-m', args.commitMessage], { signal: exec.signal })
            if (commit.code !== 0) throw new Error(`[harness-github] git commit 失败:${commit.stderr.trim()}`)
          } else {
            guidanceParts.push(
              '工作区有未提交改动,未自动处理。手动执行:',
              '  git add -A',
              '  git commit -m "<提交信息>"',
            )
          }
        }

        // 3) 提交后重新读取 ahead/behind/unpushed/upstream(用显式 range,避免对称差歧义)
        const upstreamRaw = await git(dir, ['rev-parse', '--abbrev-ref', '--symbolic-full-name', '@{u}'], { signal: exec.signal })
        const upstream = upstreamRaw.code === 0 ? upstreamRaw.stdout.trim() : ''
        let ahead = 0
        let behind = 0
        if (upstream) {
          ahead = Number(((await git(dir, ['rev-list', '--count', `${upstream}..HEAD`], { signal: exec.signal })).stdout.trim()) || 0)
          behind = Number(((await git(dir, ['rev-list', '--count', `HEAD..${upstream}`], { signal: exec.signal })).stdout.trim()) || 0)
        } else {
          // 无上游:HEAD 全部提交都视为未推送
          ahead = Number(((await git(dir, ['rev-list', '--count', 'HEAD'], { signal: exec.signal })).stdout.trim()) || 0)
        }
        dirty = (await git(dir, ['status', '--porcelain'], { signal: exec.signal })).stdout.trim().length > 0
        const unpushed = ahead

        // 4) 决定是否需要推送(upstream 未设时需确认存在 remote,否则只能给指引)
        let needPush = false
        let hasRemote = false
        if (upstream) {
          hasRemote = true
          if (ahead > 0) {
            needPush = true
            guidanceParts.push(`有 ${ahead} 个本地提交未推送:git push`)
          }
        } else {
          const remoteOut = await git(dir, ['remote'], { signal: exec.signal })
          hasRemote = remoteOut.code === 0 && remoteOut.stdout.trim().length > 0
          if (hasRemote && (ahead > 0 || args.autoCommit || args.createPR)) {
            needPush = true
            guidanceParts.push(`分支 ${branch} 无上游,首次推送:git push -u origin ${branch}`)
          } else if (!hasRemote && (ahead > 0 || args.autoCommit)) {
            guidanceParts.push(
              `当前仓库没有配置远程(remote),无法推送。请先:git remote add origin <url> 或直接克隆已有仓库。`,
            )
          }
        }

        // 5) 只读:查该 head 分支是否已有 open PR(防重复)
        let existing = []
        try {
          existing = (await client.listPRsByHead(owner, repo, branch, { signal: exec.signal })) ?? []
        } catch { existing = [] }

        // 6) 决定是否需要创建 PR
        const base = args.base ?? (await client.repo(owner, repo, { signal: exec.signal })).default_branch ?? 'main'
        let needPR = false
        if (args.createPR && existing.length === 0) {
          if (base === branch) {
            guidanceParts.push(`目标分支 base 与当前分支 ${branch} 相同,不能创建 PR —— 请切到独立分支或指定 base。`)
          } else {
            needPR = true
          }
        }

        const guidance = guidanceParts.join('\n')
        // 纯指引路径:无任何远程写操作
        if (!needPush && !needPR) {
          if (existing.length > 0) {
            const p = existing[0]
            return {
              dir, branch, upstream, ahead, behind, unpushed, dirty,
              action: 'existing', prNumber: p.number, prUrl: p.html_url ?? '',
              guidance: `该分支已有 open PR #${p.number},无需重复创建。${guidance}`,
            }
          }
          return {
            dir, branch, upstream, ahead, behind, unpushed, dirty,
            action: 'guidance', prNumber: 0, prUrl: '',
            guidance: guidance || '一切已就绪(全部已推送,无需创建 PR)。',
          }
        }

        // 7) 一次审批覆盖本次全部远程写操作(推送 + 创建 PR);拒绝则零副作用
        const actions = []
        if (needPush) actions.push(`推送 ${branch} → ${owner}/${repo}${upstream ? '' : '(首次 -u)'}`)
        if (needPR) actions.push(`创建 PR:${base} ← ${branch}「${args.title ?? `${branch}: 变更`}」`)
        await requestApproval(ctx, exec, `准备 PR:${actions.join('; ')}`)

        // 8) 推送
        if (needPush) {
          const pushArgs = upstream ? ['push'] : ['push', '-u', 'origin', branch]
          const push = await git(dir, pushArgs, { signal: exec.signal })
          if (push.code !== 0) throw new Error(`[harness-github] git push 失败:${push.stderr.trim()}`)
        }

        // 9) 创建 PR
        if (needPR) {
          const created = await client.createPR(owner, repo, {
            title: args.title ?? `${branch}: 变更`,
            body: args.body,
            base,
            head: branch,
            draft: false,
          }, { signal: exec.signal })
          return {
            dir, branch, upstream, ahead, behind, unpushed, dirty,
            action: 'created', prNumber: created.number, prUrl: created.html_url ?? '',
            guidance,
          }
        }
        if (existing.length > 0) {
          const p = existing[0]
          return {
            dir, branch, upstream, ahead, behind, unpushed, dirty,
            action: 'existing', prNumber: p.number, prUrl: p.html_url ?? '',
            guidance,
          }
        }
        return {
          dir, branch, upstream, ahead, behind, unpushed, dirty,
          action: 'pushed', prNumber: 0, prUrl: '',
          guidance,
        }
      },
    },
  ]
}"
    },
    {
      "path": "lib/workflow.js",
      "content": "/**
 * harness-github —— 系统提示工作流 section(github:workflow)。
 *
 * 纯内容模块:输入插件的系统提示,引导模型按 Codex GitHub 插件的语义处理
 * PR / issue / CI 与发布流程。text 是函数形式,保持一致的同时便于测试断言。
